package com.nigson.acceptance.order;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.context.ConfigurableApplicationContext;
import com.nigson.commerce.order.CheckoutPayments;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.acceptance.files.FileHttpAcceptance;
import static org.assertj.core.api.Assertions.*;
public final class OrderHttpAcceptance {
 private OrderHttpAcceptance(){}
 public static final class Fixture implements AutoCloseable {
  public final OrderFixture order;public final FileHttpAcceptance.Workload workload;
  public Fixture()throws Exception{String url=System.getenv("NIGSON_TEST_JDBC_URL");if(url==null||!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_HTTP_ORDER_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");order=new OrderFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));workload=new FileHttpAcceptance.Workload();}
  public void configure(Map<String,Object> p){order.jdbc.update("UPDATE commerce.market SET enabled=false WHERE id=?",order.prices.market);p.put("NIGSON_OIDC_ISSUER",workload.issuer);p.put("NIGSON_OIDC_JWKS",workload.issuer+"/protocol/openid-connect/certs");p.put("NIGSON_PROVIDERS_ENABLED","true");p.put("PAYSTACK_MODE","MOCK");p.put("PAYSTACK_BASE_URL",order.endpoint);p.put("PAYSTACK_SECRET_KEY","sk_mock_nigson");p.put("NIGSON_ORDER_CHECKOUT_ENABLED","true");p.put("NIGSON_ORDER_PAYMENT_MODE","MOCK");p.put("NIGSON_ORDER_MERCHANT_ACCOUNT","SYNTHETIC_OFFLINE_MERCHANT");p.put("NIGSON_ORDER_STOCK_LOCATION_PRIORITY",order.location.toString());p.put("NIGSON_PRICING_CHECKOUT_ENABLED","true");p.put("NIGSON_PRICING_PROVIDER_MODE","MOCK");p.put("NIGSON_PRICING_PAYMENT_APPROVAL","SYNTHETIC_PAYMENT_NOT_QUALIFIED");p.put("NIGSON_PRICING_CARRIER_APPROVAL","SYNTHETIC_CARRIER_NOT_QUALIFIED");String snapshot=order.jdbc.queryForObject("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",String.class,order.quote.id());p.put("NIGSON_PRICING_PROVIDER_APPROVAL_UNTIL",EventCodec.JSON.readTree(snapshot).path("providerProof").path("validUntil").asString());p.put("NIGSON_PRODUCT_PHASE","3");p.put("NIGSON_PRICING_DISTRIBUTOR_ENTITLEMENT","SYNTHETIC_DISTRIBUTOR_BUY");}
  public void close(){try{order.close();}finally{workload.close();}}
 }
 private record Browser(String cookie,String csrf){}
 private static Browser browser(JdbcSessionTrust sessions,JdbcTemplate jdbc,UUID party){String issuer=jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);String subject=jdbc.queryForObject("SELECT identity_subject FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String csrf=JdbcSessionTrust.opaque();String id=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,subject,Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),csrf,SessionRecord.TokenState.READY));return new Browser("__Host-nigson-session="+id,csrf);}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder r)throws Exception{return http.send(r.timeout(Duration.ofSeconds(15)).build(),HttpResponse.BodyHandlers.ofString());}
 private static HttpRequest.Builder command(String url,Browser b,String key,String body,Long version){var r=HttpRequest.newBuilder(URI.create(url)).header("Cookie",b.cookie()).header("X-CSRF-TOKEN",b.csrf()).header("Idempotency-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));if(version!=null)r.header("If-Match","\""+version+"\"");return r;}
 private static HttpRequest.Builder get(String url,Browser b){return HttpRequest.newBuilder(URI.create(url)).header("Cookie",b.cookie()).GET();}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base,Fixture fixture)throws Exception{
  if(fixture==null)return;var f=fixture.order;f.jdbc.update("UPDATE commerce.market SET enabled=true WHERE id=?",f.prices.market);var sessions=app.getBean(JdbcSessionTrust.class);var browsers=new ArrayList<Browser>();try{var customer=browser(sessions,f.jdbc,f.prices.customer.party());var operations=browser(sessions,f.jdbc,f.operations.party());browsers.add(customer);browsers.add(operations);String checkout=base+"/api/v1/checkout/attempts",body=EventCodec.JSON.writeValueAsString(f.input);assertThat(send(http,HttpRequest.newBuilder(URI.create(checkout)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body))).statusCode()).isEqualTo(401);assertThat(send(http,command(checkout,new Browser(customer.cookie(),"wrong"),"csrf",body,null)).statusCode()).isEqualTo(401);assertThat(send(http,command(checkout,customer,"closed",body.replace("}",",\"amount\":\"0.00\"}"),null)).statusCode()).isEqualTo(400);
   var created=send(http,command(checkout,customer,"http-checkout",body,null));assertThat(created.statusCode()).as("checkout: %s",created.body()).isEqualTo(201);assertThat(created.headers().firstValue("Cache-Control")).hasValue("no-store");var result=EventCodec.JSON.readTree(created.body());String id=result.path("order").path("id").asString();long version=result.path("order").path("version").asLong();assertThat(created.headers().firstValue("ETag")).hasValue("\""+version+"\"");assertThat(result.path("payment").path("state").asString()).isEqualTo("PENDING");assertThat(result.path("payment").path("checkoutUrl").isNull()).isTrue();assertThat(send(http,command(checkout,customer,"http-checkout",body,null)).body()).isEqualTo(created.body());assertThat(created.body()).doesNotContain("merchantAccount","carrierSnapshot","commercialSnapshot","objectKey","synthetic-refresh");var owned=send(http,get(base+"/api/v1/orders/"+id,customer));assertThat(owned.statusCode()).isEqualTo(200);assertThat(send(http,get(base+"/api/v1/orders?size=1",customer)).statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(send(http,get(base+"/api/v1/orders",customer)).body()).path("items").size()).isEqualTo(1);assertThat(send(http,get(base+"/api/v1/orders?partyId="+f.operations.party(),customer)).statusCode()).isEqualTo(400);assertThat(send(http,get(base+"/api/v1/staff/orders",customer)).statusCode()).isEqualTo(403);assertThat(send(http,get(base+"/api/v1/staff/orders?status=PENDING",operations)).statusCode()).isEqualTo(200);
   String proofUrl=base+"/internal/v1/purchase-proofs",proofBody=EventCodec.JSON.writeValueAsString(Map.of("partyId",f.prices.customer.party(),"orderLineId",result.path("order").path("lines").get(0).path("id").asString(),"productId",f.prices.marketFixture.product));for(var invalid:List.of(List.of("purchase-proof.read","nigson-integration","nigson-commerce"),List.of("purchase-proof.write","nigson-experience","nigson-commerce"),List.of("purchase-proof.read","nigson-experience","nigson-experience"))){String token=fixture.workload.token(invalid.get(0),invalid.get(1),invalid.get(2));assertThat(send(http,HttpRequest.newBuilder(URI.create(proofUrl)).header("Authorization","Bearer "+token).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(proofBody))).statusCode()).isEqualTo(401);}String proofToken=fixture.workload.token("purchase-proof.read","nigson-experience","nigson-commerce");var pendingProof=send(http,HttpRequest.newBuilder(URI.create(proofUrl)).header("Authorization","Bearer "+proofToken).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(proofBody)));assertThat(pendingProof.statusCode()).as("proof: %s",pendingProof.body()).isEqualTo(201);assertThat(EventCodec.JSON.readTree(pendingProof.body()).path("eligible").asBoolean()).isFalse();f.admin("progress",Map.of("id",result.path("payment").path("reference").asString(),"status","success"));app.getBean(CheckoutPayments.class).inspect(UUID.fromString(id),UUID.randomUUID());var paid=EventCodec.JSON.readTree(send(http,get(base+"/api/v1/orders/"+id,customer)).body());assertThat(paid.path("status").asString()).isEqualTo("PAID");long paidVersion=paid.path("version").asLong();String processing=base+"/api/v1/staff/orders/"+id+"/processing",reason="{\"reason\":\"Synthetic authorized paid processing\"}";var processed=send(http,command(processing,operations,"http-process",reason,paidVersion));assertThat(processed.statusCode()).as("processing: %s",processed.body()).isEqualTo(200);assertThat(send(http,command(processing,operations,"http-stale",reason,paidVersion)).statusCode()).isEqualTo(412);var eligible=send(http,HttpRequest.newBuilder(URI.create(proofUrl)).header("Authorization","Bearer "+proofToken).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(proofBody)));assertThat(eligible.statusCode()).isEqualTo(201);var proofNode=EventCodec.JSON.readTree(eligible.body());assertThat(proofNode.path("eligible").asBoolean()).isTrue();assertThat(proofNode.propertyNames()).containsExactlyInAnyOrder("eligible","reasonCode","revision");
   var second=f.secondBuyer();var other=browser(sessions,f.jdbc,second.actor().party());browsers.add(other);assertThat(send(http,get(base+"/api/v1/orders/"+id,other)).statusCode()).isEqualTo(404);var secondResult=send(http,command(checkout,other,"second-http-checkout",EventCodec.JSON.writeValueAsString(second.input()),null));assertThat(secondResult.statusCode()).as("second: %s",secondResult.body()).isEqualTo(201);var secondNode=EventCodec.JSON.readTree(secondResult.body());String secondId=secondNode.path("order").path("id").asString();f.admin("progress",Map.of("id",secondNode.path("payment").path("reference").asString(),"status","failed"));app.getBean(CheckoutPayments.class).inspect(UUID.fromString(secondId),UUID.randomUUID());var failed=EventCodec.JSON.readTree(send(http,get(base+"/api/v1/orders/"+secondId,other)).body());String cancellation=base+"/api/v1/orders/"+secondId+"/cancellation";var cancelled=send(http,command(cancellation,other,"http-cancel","{\"reason\":\"Customer requests cancellation\"}",failed.path("version").asLong()));assertThat(cancelled.statusCode()).as("cancellation: %s",cancelled.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(cancelled.body()).path("status").asString()).isEqualTo("CANCELLED");assertThat(f.stock("reserved")).isZero();assertThat(f.stock("allocated")).isEqualByComparingTo("2");var metrics=app.getBean(io.micrometer.core.instrument.MeterRegistry.class);assertThat(metrics.get("nigson.order.commands").tag("operation","CHECKOUT").counter().count()).isEqualTo(2);for(String op:List.of("PROCESS","CANCEL","SETTLE"))assertThat(metrics.get("nigson.order.commands").tag("operation",op).counter().count()).isEqualTo(1);f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE id=?",f.role);assertThat(send(http,command(processing,operations,"http-process",reason,paidVersion)).statusCode()).isEqualTo(403);
  }finally{for(var b:browsers)sessions.logout(b.cookie().substring(b.cookie().indexOf('=')+1));}
 }
}
